    webhook_events_filter: ["completed"]
  });


    await ref.update({ genImageJson: response }); 

    return {
      id: response.id,
      status: response.status
    };
  } catch (error) {
    logging.error('Error during Replicate prediction:', error);
    throw error;
  }
};

