      return undefined; // No valid request here
    }

    const prompt = row.request
    // const prompt = `Create a detailed and vibrant image that embodies the essence of '${topic}' in a learning context. The image should feature a variety of associated items, actions, and concepts that one would expect to find within this subject. Include interactive elements such as people or characters engaging with the environment or objects that are labeled with their names in both English and the target language. The labels should be clear and legible, complementing a scene filled with activity and educational cues. The artwork must be captivating and informative, suitable for a diverse learning audience, from children to adults.`
     // API call to OpenAI
