    });

    // Retrieve only the first URL from the response because n Defaults to 1
    const firstResponseUrl = response.data[0]?.url;
    if (!firstResponseUrl) {
      throw new Error('No response data found');
    }
    // return firstResponseUrl;
    logging.log('Image generated:', firstResponseUrl)
    //Upload to filestore
    const genRequestImage = await rowy.storage.upload.url(firstResponseUrl, {
      folderPath: ref.path + '/requestUnit/'
    });
    return genRequestImage.downloadURL;

  } catch (error) {
    if (error instanceof OpenAI.APIError) {
      logging.log("OpenAI API Error:", error.name, "Status:", error.status);
