import OpenAI from "openai";
const derivative: Derivative = async ({ row, ref, db, storage, auth, logging }) => {
  try {
    const openaiApiKey = await rowy.secrets.get("openai");
    if (!openaiApiKey) {
      logging.error('OpenAI API key not found');
    }
    const openai = new OpenAI({ apiKey: openaiApiKey });

    // Validate row data
    if (!row.uploadImage && !row.request) {
      logging.log('Neither uploadImage nor request is provided. Exiting function.');
      return 'No action needed';
    }

    const userText = `Target language: ${row.level?.language || 'English'}. User's mother tongue: ${row.motherTongue || 'en'}. User's level: ${row.level?.category || 'Beginner'} ${(row.level?.score !== undefined && row.level.score !== null) ? `${row.level.score}/5` : '1/5'}`;
    // Initialize variables for model, focusOn, and userContent
    let model = 'gpt-4-vision-preview'; // Default model
    let focusOn = 'image'; // Default focus
    let userContent;

    // Update variables based on the presence of row.request
    if (!row.uploadImage) {
      if (!row.request) {
        return 'No valid input found';
      }
      model = 'gpt-4-1106-preview';
      focusOn = 'topic';
      userContent = `TOPIC REQUEST: ${row.request}. ${userText} \\n YOUR REPLY JSON: `;
    } else {
        userContent = [
                { type: "text", text: userText },
                { type: "image_url", image_url: row.uploadImage },
            ];
    };


    const systemprompt = `Imagine that you are an AI language teacher working on a language learning app inspired by Duolingo's style. Your task is to create a language learning unit customized to the user's specified level and '${focusOn}' request. The unit should consist of lessons that follow Duolingo's engaging format.
                            Based on these inputs, generate a language learning unit in the form of a JSON object with the following structure:
                              {
                                "unit": "<unit name>",                        
                                "lessons": [
                                  {
                                    "title": "<title>",
                                    "description": "<description>",
                                    "words": []
                                  },
                                  ...
                                ]
                              } 
                            `;

    // API call to OpenAI
    const response = await openai.chat.completions.create({
      model: model,
      messages: [
        { role: "system", content: systemprompt },
        { role: "user", content: userContent },
      ],
      temperature: 1,
      max_tokens: 4095,
      top_p: 1,
      frequency_penalty: 0,
      presence_penalty: 0,
    });

    const responseData = response.choices[0].message?.content;
    if (!responseData) {
      logging.error('No response data found');
    }

    return JSON.parse(responseData);
    /*
    // Regular expression to find only JSON object
      const regex = `/(\{.*\}|\[.*\])/s`; // find a JSON object or array /(\{.*\}|\[.*\])/s
      // Extract JSON string using the regular expression.
      const jsonPart = responseData.match(regex);

      if (jsonPart) {
        try {
            // Parse and return the JSON object/array
            return JSON.parse(jsonPart[0]);
        } catch (error) {
            // Handle parsing error (invalid JSON)
            logging.error("Invalid JSON:", error);
            return null;
        }
      } else {
        logging.error('JSON part not found in the response data');
        return null;
      }
      */


  } catch (error) {
    if (error instanceof OpenAI.APIError) {
      logging.log("OpenAI API Error:", error.name, "Status:", error.status);
    } else {
      logging.log("Error:", error.message);
    }

    return undefined;
  }
};

