const basicParser: Parser = async ({ req, db, ref }) => {
    const { body } = req;

    // auditField
    const _updatedBy = await rowy.metadata.serviceAccountUser()

    const { id } = body
    const query = await ref.where("genImageJson.id", "==", id).get()
    if (query.empty) {
        return null
    } else {
        await query.docs[0].ref.update({ genImageJson: body.output, _updatedBy })
        return null
    }

}
